import{c as a,Q as e,j as o,m as p}from"./chunks/framework.hhGiamYR.js";const q=JSON.parse('{"title":"弗利那三天——关于言辞的重量，和一位只用行动说话的女伯爵","description":"1499年7月，29岁的马基雅维利第一次独自出使弗利。他带去了蜡印国书、成堆的漂亮话，被卡泰丽娜·斯福尔扎用一句\\"言辞满意、行为不满\\"打回原形。这一课预示了《君主论》的实效真理。","frontmatter":{"date":"2026-10-14T00:00:00.000Z","title":"弗利那三天——关于言辞的重量，和一位只用行动说话的女伯爵","description":"1499年7月，29岁的马基雅维利第一次独自出使弗利。他带去了蜡印国书、成堆的漂亮话，被卡泰丽娜·斯福尔扎用一句\\"言辞满意、行为不满\\"打回原形。这一课预示了《君主论》的实效真理。"},"headers":[],"relativePath":"research/the-weight-of-words/index.md","filePath":"research/the-weight-of-words/index.md"}'),r={name:"research/the-weight-of-words/index.md"};function i(l,t,u,h,d,n){return e(),o("div",null,[...t[0]||(t[0]=[p('<h1 id="弗利那三天——关于言辞的重量-和一位只用行动说话的女伯爵" tabindex="-1">弗利那三天——关于言辞的重量，和一位只用行动说话的女伯爵 <a class="header-anchor" href="#弗利那三天——关于言辞的重量-和一位只用行动说话的女伯爵" aria-label="Permalink to &quot;弗利那三天——关于言辞的重量，和一位只用行动说话的女伯爵&quot;">​</a></h1><p>1499 年 7 月，我二十九岁，第一次独自出使。</p><p>在此之前，我随团去过法国宫廷，尝过被轻慢的滋味，但那次至少还有大使挡在我前面。这一次不同。十人委员会交给我一封盖了蜡印的国书，一份写了满页理由的训令，让我一个人骑马去弗利，面见卡泰丽娜·斯福尔扎女伯爵，谈她儿子奥塔维亚诺的雇佣军合同续签。</p><p>我那时以为自己带着佛罗伦萨的威严上路了。我错了。而且错得比我想象的更彻底。</p><h2 id="我带去的是什么" tabindex="-1">我带去的是什么 <a class="header-anchor" href="#我带去的是什么" aria-label="Permalink to &quot;我带去的是什么&quot;">​</a></h2><p>训令写得很周详。它要我&quot;如此这般明确无误地为我方立场辩护，以使领主阁下了解我们的所作所为全都是出于理性&quot;，还要我&quot;务必时刻出言谨慎，表达友善之情&quot;。说到底，交到我手里的是一整套话术：我们共和国&quot;背上了沉重的负担&quot;，无力供养；我们并非拒绝她的效劳，只是&quot;无力&quot;；我们给奥塔维亚诺一份合同，纯粹&quot;出于对她的看重和热爱&quot;。</p><p>每一句都滴水不漏，每一句都漂亮。漂亮到我在去弗利的路上，自己都信了几分。</p><p>卡泰丽娜是什么人呢？弗朗切斯科·斯福尔扎——后来的米兰公爵——的私生女，弗利和伊莫拉的女领主。她先嫁了领主莫吉罗拉·里亚里奥，丈夫死后又嫁了亚科波·费奥，最后嫁了美第奇家的&quot;平民&quot;乔瓦尼。1498 年 9 月 14 日，这第三任丈夫死在弗利。她带着前夫的私生子奥塔维亚诺，和第三任丈夫留下的幼子&quot;黑条&quot;乔瓦尼，一个人在罗马涅的边境上守着一座城。</p><p>她守的不是一座城，是四面环敌的局面——威尼斯人盯着她的领地，米兰公爵等着她表态，佛罗伦萨想压她的价。而她唯一的本钱，就是手里这支雇佣军，和她自己那张不肯低头的脸。</p><h2 id="她回给我的是什么" tabindex="-1">她回给我的是什么 <a class="header-anchor" href="#她回给我的是什么" aria-label="Permalink to &quot;她回给我的是什么&quot;">​</a></h2><p>我直到夜里二十二点才见到她。大厅里只有三个人：她、米兰公爵的代理人乔瓦尼·达·卡萨莱，和我。我按训令把该说的话都说了，说到最后，是那句最能打动人的——我们&quot;出于她的伟大功绩所产生的热爱&quot;，才派我来。</p><p>她听完，只回了一句：</p><blockquote><p>📖 <strong>原文</strong>：《政务与外交著作·出使卡泰丽娜》，发自弗利，1499 年 7 月 17 日</p><p>&quot;夫人回答说，诸位大人的言辞总是能让她满意，但你们的行为则并不总是让她高兴，且她从未得到与她的服务价值相称的报偿。&quot;</p><p>— 全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/diplomatic/upper/diplomatic-upper.md" target="_blank" rel="noreferrer">machiavelli/diplomatic/upper/diplomatic-upper.md</a></p></blockquote><p>这句话把我准备了一路的话术整个拆开了。她没有反驳我的理由，没有跟我争辩合同条款，她只是把&quot;言辞&quot;和&quot;行为&quot;摆在一起，让我自己看见那道缝。</p><p>我带的每句话都是真的——我们确实负担沉重，我们确实对她怀有善意。可这些话合起来，掩盖不了一个事实：我们想用更少的钱，留住一个我们其实需要的人。她看见了。而她的报复方式，是让我们也看见。</p><h2 id="言辞的重量-由行动称量" tabindex="-1">言辞的重量，由行动称量 <a class="header-anchor" href="#言辞的重量-由行动称量" aria-label="Permalink to &quot;言辞的重量，由行动称量&quot;">​</a></h2><p>接下来三天，我在她的秘书和她的沉默之间来回奔走。她从不拒绝，也从不答应。她让秘书转告我，米兰公爵开了更好的条件，她夹在中间&quot;无所适从&quot;。而我在写给十人委员会的信里，终于写下一句连我自己都愣了一下的实话：</p><blockquote><p>📖 <strong>原文</strong>：《政务与外交著作·出使卡泰丽娜》，发自弗利，1499 年 7 月 18 日</p><p>&quot;我对此尽力做了答复，但还是不免注意到，言辞和论证若不是至少部分由行动来支持，是满足不了夫人的。&quot;</p><p>— 全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/diplomatic/upper/diplomatic-upper.md" target="_blank" rel="noreferrer">machiavelli/diplomatic/upper/diplomatic-upper.md</a></p></blockquote><p>这句话不是写给十人委员会看的漂亮汇报，是一个刚被现实上了一课的年轻人，在夜里伏案时吐出来的真话。</p><p>我还记下了她另一句更狠的话。她说，其他人为我们出的力不如她大，酬金却涨了；她和儿子的酬金反倒降了。这让她难以相信，诸位大人对她竟&quot;如此忽视&quot;。这些字眼现在读来平平，可在当时，她每说一句，我手里的训令就轻一分。到最后，我意识到一件事：谈判桌上真正的力量从来不在国书和训令里，而在对方敢不敢转身走掉。卡泰丽娜敢。因为她守的是自己的墙、自己的兵，而我只是一个替十人委员会传话的人。</p><p>她没输。一年后，1500 年 6 月 12 日，切萨雷·博尔贾攻陷弗利，她被俘。可即便被俘，她也只败给了炮火和机运，没有败给任何一张嘴。</p><h2 id="这一课去了哪里" tabindex="-1">这一课去了哪里 <a class="header-anchor" href="#这一课去了哪里" aria-label="Permalink to &quot;这一课去了哪里&quot;">​</a></h2><p>我把这三天写进急件，寄回佛罗伦萨。很多年后，当我在乡下写那本讲君主的薄册子时，这三天又从记忆里浮了上来。《君主论》第十五章里那句话——人们实际上怎样生活，与人们应当怎样生活，差距如此之大——它的根，有一半埋在那年弗利燥热的七月。</p><p>一个女伯爵用行动教会我的，比我在法国宫廷听过的任何一场雄辩都多：言辞若没有行动垫底，再周全也是空的。这不是修辞上的谦辞，是一个谈判者必须攥在手里的常识。你可以在纸上把话说到天衣无缝，可对方若在现实里握着一支军队、一座城，和一个不肯低头的女人，你的天衣无缝就只是天衣无缝——它挡不住任何一扇会关上的门。</p><p>我后来很少再犯这个错。因为每次我张嘴想说漂亮话的时候，都会想起 1499 年 7 月那间大厅里，一个穿暗红天鹅绒的女人，用一句话让我带来的全部文件变成了废纸。</p><p>尼科洛·马基雅维利，圣卡夏诺</p>',26)])])}const s=a(r,[["render",i]]);export{q as __pageData,s as default};
